#include <WiFi.h>
#include <WebServer.h>
#include <Preferences.h>

WebServer server(80);
Preferences preferences;

String ssid = "";
String password = "";
String serverUrl = "https://api.xiaozhi.me";
int servoPin = 4; // Chân mặc định ban đầu

bool isBotSpeaking = false;
unsigned long lastMoveTime = 0;

// Hàm điều khiển góc Servo bằng PWM phần cứng của ESP32-S3 (Không cần thư viện)
void writeServo(int angle) {
    angle = constrain(angle, 0, 180);
    // Chuyển góc (0-180 độ) thành chu kỳ xung PWM (tương ứng 500us đến 2400us ở tần số 50Hz)
    int duty = map(angle, 0, 180, 1638, 7864); 

    // Sử dụng tính năng LEDC native của ESP32-S3
    ledcAttach(servoPin, 50, 16); // Tần số 50Hz, độ phân giải 16-bit
    ledcWrite(servoPin, duty);
}

// Tạo trang HTML giao diện quản lý trên Mi Pad 6
String getHTML() {
    String html = R"rawliteral(
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="UTF-8">
      <meta name="viewport" content="width=device-width, initial-scale=1.0">
      <title>Bang Dieu Khien Bot AI</title>
      <style>
        body { font-family: Arial; background: #121212; color: #fff; text-align: center; padding: 10px; margin: 0; }
        .card { background: #1e1e1e; padding: 15px; margin: 10px auto; width: 95%; max-width: 450px; border-radius: 12px; box-shadow: 0 4px 10px rgba(0,0,0,0.5); text-align: left; }
        h2 { color: #00d2ff; text-align: center; }
        h3 { margin-top: 5px; color: #ffeb3b; text-align: center; }
        button { padding: 12px 18px; font-size: 16px; margin: 6px; cursor: pointer; border: none; border-radius: 8px; font-weight: bold; color: white; width: 30%; }
        .btn-left { background: #17a2b8; }
        .btn-center { background: #6c757d; }
        .btn-right { background: #ffc107; color: black; }
        .btn-on { background: #28a745; width: 48%; }
        .btn-off { background: #dc3545; width: 48%; }
        .btn-save { background: #007BFF; width: 100%; margin-top: 10px; }
        input { width: 100%; padding: 8px; margin: 5px 0 10px 0; box-sizing: border-box; background: #2c2c2c; border: 1px solid #444; color: #fff; border-radius: 4px; }
        .text-center { text-align: center; }
      </style>
    </head>
    <body>
      <h2>🤖 Bảng Điều Khiển Bot AI</h2>

      <!-- Điều khiển Servo nhanh -->
      <div class="card">
        <h3>Điều Khiển Nhanh Servo</h3>
        <div class="text-center">
          <button class="btn-left" onclick="sendCmd('left')">⬅️ Trái</button>
          <button class="btn-center" onclick="sendCmd('center')">⏺️ Giữa</button>
          <button class="btn-right" onclick="sendCmd('right')">➡️ Phải</button>
          <br>
          <button class="btn-on" onclick="sendCmd('speak_on')">🗣️ Bật Gật Gù</button>
          <button class="btn-off" onclick="sendCmd('speak_off')">🛑 Dừng Gật</button>
        </div>
      </div>

      <!-- Cài đặt hệ thống & tùy chỉnh chân -->
      <div class="card">
        <h3>Cài Đặt Hệ Thống & Chân Cắm</h3>
        <form action="/save" method="POST">
          <label><b>Tên Wi-Fi (SSID):</b></label>
          <input type="text" name="ssid" value="REPLACE_SSID" placeholder="Nhập tên Wi-Fi">

          <label><b>Mật khẩu Wi-Fi:</b></label>
          <input type="password" name="pass" placeholder="Để trống nếu không đổi">

          <label><b>Server URL (ChatGPT/Backend):</b></label>
          <input type="text" name="server" value="REPLACE_SERVER" placeholder="https://api.yourserver.com">

          <label><b>Chân GPIO Servo (Tùy chỉnh):</b></label>
          <input type="number" name="pin" value="REPLACE_PIN" placeholder="VD: 4, 5, 6, 7...">

          <button type="submit" class="btn-save">Lưu Cấu Hình & Khởi Động Lại</button>
        </form>
      </div>

