    )rawliteral";

    html.replace("REPLACE_SSID", ssid);
    html.replace("REPLACE_SERVER", serverUrl);
    html.replace("REPLACE_PIN", String(servoPin));
    return html;
}

void handleRoot() {
    server.send(200, "text/html", getHTML());
}

void handleCommand() {
    if (server.hasArg("action")) {
        String action = server.arg("action");
        if (action == "left") {
            writeServo(30); // Góc trái
            isBotSpeaking = false;
        } else if (action == "right") {
            writeServo(150); // Góc phải
            isBotSpeaking = false;
        } else if (action == "center") {
            writeServo(90); // Giữa
            isBotSpeaking = false;
        } else if (action == "speak_on") {
            isBotSpeaking = true; // Bật gật gù
        } else if (action == "speak_off") {
            isBotSpeaking = false;
            writeServo(90);
        }
        server.send(200, "text/plain", "OK");
    }
}

void handleSave() {
    if (server.hasArg("ssid") && server.hasArg("server")) {
        preferences.begin("bot-config", false);
        preferences.putString("ssid", server.arg("ssid"));

        String newPass = server.arg("pass");
        if (newPass.length() > 0) {
            preferences.putString("pass", newPass);
        }

        preferences.putString("server", server.arg("server"));
        preferences.putInt("pin", server.arg("pin").toInt());
        preferences.end();

        server.send(200, "text/html", "<h3>Đã lưu cấu hình thành công! Thiết bị đang khởi động lại...</h3>");
        delay(2000);
        ESP.restart();
    } else {
        server.send(400, "text/plain", "Thiếu thông tin!");
    }
}

void setup() {
    Serial.begin(115200);
    delay(1000);

    // Đọc thông số đã lưu từ bộ nhớ Flash
    preferences.begin("bot-config", true);
    ssid = preferences.getString("ssid", "");
    password = preferences.getString("pass", "");
    serverUrl = preferences.getString("server", "https://api.xiaozhi.me");
    servoPin = preferences.getInt("pin", 4);
    preferences.end();

    // Đưa servo về giữa khi khởi động
    writeServo(90);

    // Kết nối Wi-Fi
    if (ssid.length() > 0) {
        WiFi.begin(ssid.c_str(), password.c_str());
        int timeout = 0;
        while (WiFi.status() != WL_CONNECTED && timeout < 20) {
            delay(500);
            timeout++;
        }
    }

    // Nếu không kết nối được Wi-Fi -> Phát AP Mode để vào web cấu hình
    if (WiFi.status() != WL_CONNECTED) {
        WiFi.softAP("ESP32-Bot-Config", "12345678");
    }

    server.on("/", handleRoot);
    server.on("/cmd", handleCommand);
    server.on("/save", HTTP_POST, handleSave);
    server.begin();
}

void loop() {
    server.handleClient();

    // Hiệu ứng gật gù ngẫu nhiên khi bật trạng thái nói
    if (isBotSpeaking) {
        if (millis() - lastMoveTime > 200) {
            int randomAngle = random(70, 110);
            writeServo(randomAngle);
            lastMoveTime = millis();
        }
    }
}
